# ---------------- settings ----------------
GRID      = 3                # atoms per side of the crystal (3 -> 27 atoms)
N6S       = 100_000          # grains in each atom's 6s cloud
N5D       = 30_000           # grains in each atom's 5d cloud
NCORE     = 8_000            # grains in each atom's core
SECONDS   = 30
FPS       = 30
ENGINE    = "EEVEE"
SAMPLES   = 64
RES_SCALE = 100
POINT_PX  = 5.0              # size of each grain on screen
BRIGHT    = 1.5              # strength of the lights
OUTPUT    = os.path.join(os.path.expanduser("~"), "OrbitalRenders", "mercury")
NF = SECONDS * FPS
LENS = 43.5; KH = 18.0 / LENS; PXK = KH / 960.0
R6, R5, RC = 10.0, 5.0, 1.2  # outer radius of each cloud
SPACING = 2 * R6 * 0.8       # distance between neighbour atoms
SHRINK = 0.83                # relativistic contraction of 6s

# ---------------- timeline ----------------
T_FREEZE = (2.0, 4.4)                     # liquid -> crystal ("without Einstein")
T_ZIN, T_ZOUT = (4.6, 6.2), (13.6, 15.0)  # dive into 1 atom and back
T_SPEED = (6.0, 9.0)                      # 0 -> 58 % of c
T_SHRINK = (9.6, 11.6)                    # 6s contracts
T_BONDS = (16.6, 18.4)                    # bonds fade away
T_TEMP = (20.0, 23.0)                     # +82 C -> -39 C
T_MELT = (21.2, 24.4)                     # crystal -> liquid
T_PAN = (19.0, 25.6)                      # atoms move up, thermometer below
T_CAT = (17.0, 17.4)                      # the hidden cat
HG6 = (0.80, 0.87, 0.98); HG5 = (0.55, 0.68, 0.92); HGC = (0.88, 0.95, 1.0)

def ease(u):
    u = np.clip(u, 0, 1); return u * u * (3 - 2 * u)
def ef(u): return float(ease(u))
T = np.arange(NF) / FPS
def ramp(a, b): return ease((T - a) / (b - a))
def fade(pairs): return np.interp(T, [p[0] for p in pairs], [p[1] for p in pairs])
def show(a, b, fi=0.5, fo=0.4): return [(0, 0), (max(a, 0.001), 0), (a + fi, 1), (b, 1), (b + fo, 0), (SECONDS, 0)]
def window(a, b, c, d):
    return np.array([ef((t - a) / (b - a)) - ef((t - c) / (d - c)) for t in T])
ZIN = window(*T_ZIN, *T_ZOUT)
MELT = np.clip(1 - ramp(*T_FREEZE) + ramp(*T_MELT), 0, 1)
PAN = window(T_PAN[0], T_PAN[0] + 1.0, T_PAN[1], T_PAN[1] + 1.0)

# ---------------- helpers ----------------
def clear_scene():
    for ob in list(bpy.data.objects): bpy.data.objects.remove(ob, do_unlink=True)
    for coll in (bpy.data.meshes, bpy.data.curves, bpy.data.materials, bpy.data.cameras, bpy.data.lights, bpy.data.actions, bpy.data.images):
        for b in list(coll):
            if b.users == 0: coll.remove(b)
    for ng in list(bpy.data.node_groups):
        if ng.users == 0: bpy.data.node_groups.remove(ng)

def link(ob):
    bpy.context.scene.collection.objects.link(ob); return ob

def fcurves_of(idblock):
    act = idblock.animation_data.action
    if hasattr(act, "fcurves"):
        try:
            if len(act.fcurves): return list(act.fcurves)
        except Exception: pass
    out = []
    for layer in getattr(act, "layers", []):
        for strip in layer.strips:
            for cb in strip.channelbags: out += list(cb.fcurves)
    return out

def bake(idblock, path, index, values, owner=None):
    owner = owner or idblock
    if index is None:
        setattr(idblock, path, type(getattr(idblock, path))(values[0])); idblock.keyframe_insert(path, frame=1)
    else:
        getattr(idblock, path)[index] = values[0]; idblock.keyframe_insert(path, index=index, frame=1)
    want = path if owner is idblock else idblock.path_from_id(path)
    fc = [f for f in fcurves_of(owner) if f.data_path == want and (index is None or f.array_index == index)][0]
    fc.keyframe_points.clear(); fc.keyframe_points.add(len(values))
    co = np.empty(2 * len(values), np.float32); co[0::2] = np.arange(1, len(values) + 1); co[1::2] = values
    fc.keyframe_points.foreach_set("co", co)
    interp = 0 if (index is None and isinstance(getattr(idblock, path), bool)) else 1
    try: fc.keyframe_points.foreach_set("interpolation", np.full(len(values), interp, np.int32))
    except Exception:
        for kp in fc.keyframe_points: kp.interpolation = 'LINEAR'
    fc.update()

def blend(m):
    for attr, val in (("blend_method", 'BLEND'), ("surface_render_method", 'BLENDED')):
        try: setattr(m, attr, val)
        except Exception: pass

def glow_mat(name, rgb, strength, attr=None):
    """additive emission; Value node = fade; optional geometry attribute multiplies the strength"""
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); em = N_.new("ShaderNodeEmission"); em.inputs["Color"].default_value = (*rgb, 1)
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'; mul.inputs[1].default_value = strength
    Lk.new(val.outputs[0], mul.inputs[0]); s = mul.outputs[0]
    if attr:
        at = N_.new("ShaderNodeAttribute"); at.attribute_type = 'GEOMETRY'; at.attribute_name = attr
        m2 = N_.new("ShaderNodeMath"); m2.operation = 'MULTIPLY'; Lk.new(s, m2.inputs[0]); Lk.new(at.outputs["Fac"], m2.inputs[1]); s = m2.outputs[0]
    Lk.new(s, em.inputs["Strength"])
    tr = N_.new("ShaderNodeBsdfTransparent"); add = N_.new("ShaderNodeAddShader")
    Lk.new(tr.outputs[0], add.inputs[0]); Lk.new(em.outputs[0], add.inputs[1]); Lk.new(add.outputs[0], out.inputs[0]); blend(m)
    return m, val

def glass_mat(name, rgb, opacity):
    """see-through tinted glass: transparent mixed with a little emission (works in every EEVEE version)"""
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); em = N_.new("ShaderNodeEmission")
    em.inputs["Color"].default_value = (*rgb, 1); em.inputs["Strength"].default_value = 1.0
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'; mul.inputs[1].default_value = opacity
    Lk.new(val.outputs[0], mul.inputs[0])
    tr = N_.new("ShaderNodeBsdfTransparent"); mx = N_.new("ShaderNodeMixShader")
    Lk.new(mul.outputs[0], mx.inputs[0]); Lk.new(tr.outputs[0], mx.inputs[1]); Lk.new(em.outputs[0], mx.inputs[2])
    Lk.new(mx.outputs[0], out.inputs[0]); blend(m)
    for attr, v in (("surface_render_method", 'DITHERED'), ("blend_method", 'HASHED')):   # no sorting -> the glass never vanishes
        try: setattr(m, attr, v)
        except Exception: pass
    try: m.use_backface_culling = False
    except Exception: pass
    return m, val

def image_mat(name, img):
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial")
    tex = N_.new("ShaderNodeTexImage"); tex.image = img; tex.interpolation = 'Cubic'
    em = N_.new("ShaderNodeEmission"); Lk.new(tex.outputs["Color"], em.inputs["Color"])
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'
    Lk.new(tex.outputs["Alpha"], mul.inputs[0]); Lk.new(val.outputs[0], mul.inputs[1])
    tr = N_.new("ShaderNodeBsdfTransparent"); mx = N_.new("ShaderNodeMixShader")
    Lk.new(mul.outputs[0], mx.inputs[0]); Lk.new(tr.outputs[0], mx.inputs[1]); Lk.new(em.outputs[0], mx.inputs[2])
    Lk.new(mx.outputs[0], out.inputs[0]); blend(m)
    return m, val

def M_(N_, Lk, op, a, b=None):
    n = N_.new("ShaderNodeMath"); n.operation = op
    for i, v in enumerate((a, b)):
        if v is None: continue
        if isinstance(v, (int, float)): n.inputs[i].default_value = v
        else: Lk.new(v, n.inputs[i])
    return n.outputs[0]

def new_gn(name):
    ng = bpy.data.node_groups.new(name, 'GeometryNodeTree')
    ng.interface.new_socket("Geometry", in_out='INPUT', socket_type='NodeSocketGeometry')
    ng.interface.new_socket("Geometry", in_out='OUTPUT', socket_type='NodeSocketGeometry')
    return ng, ng.nodes, ng.links, ng.nodes.new("NodeGroupInput"), ng.nodes.new("NodeGroupOutput")

def drv(N_, Lk, ob):
    oi = N_.new("GeometryNodeObjectInfo"); oi.inputs["Object"].default_value = ob
    sx = N_.new("ShaderNodeSeparateXYZ"); Lk.new(oi.outputs["Location"], sx.inputs[0]); return sx.outputs

def tube(N_, Lk, curve, radius, mat, res=8):
    circ = N_.new("GeometryNodeCurvePrimitiveCircle"); circ.inputs["Resolution"].default_value = res
    Lk.new(radius, circ.inputs["Radius"])
    c2m = N_.new("GeometryNodeCurveToMesh"); Lk.new(curve, c2m.inputs["Curve"]); Lk.new(circ.outputs["Curve"], c2m.inputs["Profile Curve"])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(c2m.outputs[0], sm.inputs["Geometry"]); return sm.outputs[0]

def lines_obj(name, segs, D, mat, thick=0.55):
    verts, edges = [], []
    for poly in segs:
        i0 = len(verts); verts.extend(poly); edges.extend((i0 + k, i0 + k + 1) for k in range(len(poly) - 1))
    me = bpy.data.meshes.new(name); me.from_pydata(verts, edges, []); me.update()
    ob = link(bpy.data.objects.new(name, me))
    ng, N_, Lk, gi, go = new_gn(name); d = drv(N_, Lk, D)
    m2c = N_.new("GeometryNodeMeshToCurve"); Lk.new(gi.outputs[0], m2c.inputs["Mesh"])
    Lk.new(tube(N_, Lk, m2c.outputs[0], M_(N_, Lk, 'MULTIPLY', d[1], thick), mat, 6), go.inputs[0])
    ob.modifiers.new(name, 'NODES').node_group = ng
    return ob


def counter_group(Dv, axis, font, mat):
    ng, N_, Lk, gi, go = new_gn("Counter%d" % axis)
    d = drv(N_, Lk, Dv)
    fl = M_(N_, Lk, 'FLOOR', M_(N_, Lk, 'ADD', d[axis], 0.5))
    vs = N_.new("FunctionNodeValueToString"); Lk.new(fl, vs.inputs["Value"])
    st = N_.new("GeometryNodeStringToCurves"); st.inputs["Size"].default_value = 70
    Lk.new(vs.outputs[0], st.inputs["String"])
    for v in ("Center", "CENTER"):
        try: st.inputs["Align X"].default_value = v; break
        except Exception:
            try: st.align_x = v; break
            except Exception: pass
    if font is not None:
        try: st.inputs["Font"].default_value = font
        except Exception:
            try: st.font = font
            except Exception: pass
    ri = N_.new("GeometryNodeRealizeInstances"); Lk.new(st.outputs[0], ri.inputs[0])
    fill = N_.new("GeometryNodeFillCurve"); Lk.new(ri.outputs[0], fill.inputs[0])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(fill.outputs[0], sm.inputs["Geometry"]); Lk.new(sm.outputs[0], go.inputs[0])
    return ng


def load_assets():
    d = os.path.join(OUTPUT, "assets"); os.makedirs(d, exist_ok=True); imgs, font = {}, None
    for n, b in ASSETS.items():
        p = os.path.join(d, n)
        with open(p, "wb") as f: f.write(base64.b64decode(b))
        if n.endswith(".ttf"):
            try: font = bpy.data.fonts.load(p, check_existing=True)
            except Exception: font = None
        else:
            im = bpy.data.images.load(p, check_existing=False); im.pack(); imgs[n[:-4]] = im
    return imgs, font


def build_world():
    w = bpy.context.scene.world or bpy.data.worlds.new("World")
    bpy.context.scene.world = w; w.use_nodes = True
    N_, Lk = w.node_tree.nodes, w.node_tree.links
    for n in list(N_): N_.remove(n)
    bg = N_.new("ShaderNodeBackground"); out = N_.new("ShaderNodeOutputWorld")
    bg.inputs["Color"].default_value = (0, 0, 0, 1); bg.inputs["Strength"].default_value = 0
    Lk.new(bg.outputs[0], out.inputs[0])

def add_bloom(scene):
    try:
        if hasattr(scene, "compositing_node_group"):
            ng = bpy.data.node_groups.get("HgBloom") or bpy.data.node_groups.new("GoldBloom", 'CompositorNodeTree')
            ng.nodes.clear()
            if not len(ng.interface.items_tree):
                ng.interface.new_socket("Image", in_out='OUTPUT', socket_type='NodeSocketColor')
            scene.compositing_node_group = ng
            N_, Lk = ng.nodes, ng.links
            rl = N_.new("CompositorNodeRLayers"); gl = N_.new("CompositorNodeGlare"); out = N_.new("NodeGroupOutput")
            gl.inputs["Type"].default_value = 'Bloom'
            gl.inputs["Threshold"].default_value = 1.0; gl.inputs["Size"].default_value = 0.5; gl.inputs["Strength"].default_value = 0.45
            Lk.new(rl.outputs["Image"], gl.inputs["Image"]); Lk.new(gl.outputs["Image"], out.inputs[0])
        else:
            scene.use_nodes = True
            nt = scene.node_tree; N_, Lk = nt.nodes, nt.links
            for n in list(N_): N_.remove(n)
            rl = N_.new("CompositorNodeRLayers"); gl = N_.new("CompositorNodeGlare"); comp = N_.new("CompositorNodeComposite")
            gl.glare_type = 'BLOOM' if 'BLOOM' in [i.identifier for i in gl.bl_rna.properties['glare_type'].enum_items] else 'FOG_GLOW'
            gl.threshold = 0.8; gl.size = 7
            Lk.new(rl.outputs["Image"], gl.inputs[0]); Lk.new(gl.outputs[0], comp.inputs[0])
    except Exception as e:
        print("Bloom not set up:", e)

def setup_render(scene):
    r = scene.render
    r.resolution_x, r.resolution_y, r.resolution_percentage = 1080, 1920, RES_SCALE
    r.fps = FPS; scene.frame_start, scene.frame_end = 1, NF
    if ENGINE == "CYCLES":
        r.engine = 'CYCLES'; scene.cycles.samples = SAMPLES
    else:
        for eng in ('BLENDER_EEVEE', 'BLENDER_EEVEE_NEXT'):
            try: r.engine = eng; break
            except Exception: pass
        try: scene.eevee.taa_render_samples = SAMPLES
        except Exception: pass
    try: scene.view_settings.view_transform = 'Standard'
    except Exception: pass
    try: r.use_motion_blur = False          # crisp grains and sharp text
    except Exception: pass
    try: r.filter_size = 2.2          # softer pixel filter: no grain, no shimmer
    except Exception: pass
    try: r.ffmpeg.constant_rate_factor = 'PERC_LOSSLESS'
    except Exception: pass
    try: pass
    except Exception: pass
    os.makedirs(OUTPUT, exist_ok=True)
    r.filepath = os.path.join(OUTPUT, "mercury.mp4")
    ims = r.image_settings
    try: ims.media_type = 'VIDEO'
    except Exception: pass
    ims.file_format = 'FFMPEG'
    r.ffmpeg.format = 'MPEG4'; r.ffmpeg.codec = 'H264'
    r.ffmpeg.constant_rate_factor = 'PERC_LOSSLESS'; r.ffmpeg.ffmpeg_preset = 'GOOD'
    r.use_lock_interface = True



# ---------------- sampling |psi|^2 (hydrogen-like radial shapes) ----------------
def laguerre(k, a, x):
    if k == 0: return np.ones_like(x)
    L0, L1 = np.ones_like(x), 1 + a - x
    for i in range(1, k):
        L0, L1 = L1, ((2 * i + 1 + a - x) * L1 - (i + a) * L0) / (i + 1)
    return L1
def shell(n, l, count, radius, seed):
    rng = np.random.default_rng(seed)
    r = np.linspace(0, 6 * n * n, 200001); rho = 2 * r / n
    R = rho ** l * np.exp(-rho / 2) * laguerre(n - l - 1, 2 * l + 1, rho)
    cdf = np.cumsum(r * r * R * R); cdf /= cdf[-1]
    rr = np.interp(rng.random(count), cdf, r)
    rr *= radius / np.interp(0.995, cdf, r)
    u = rng.normal(size=(count, 3)); u /= np.linalg.norm(u, axis=1)[:, None]
    return (u * rr[:, None]).astype(np.float32)

# ---------------- cloud nodes / materials ----------------
def cloud_group(name, Ds, Dr, mat, count):
    """Ds.x = scale, Ds.y = fraction of grains kept; Dr.x = grain radius"""
    ng, N_, Lk, gi, go = new_gn(name)
    ds = drv(N_, Lk, Ds); dr = drv(N_, Lk, Dr)
    idx = N_.new("GeometryNodeInputIndex"); pos = N_.new("GeometryNodeInputPosition")
    de = N_.new("GeometryNodeDeleteGeometry"); de.domain = 'POINT'
    Lk.new(gi.outputs[0], de.inputs["Geometry"])
    Lk.new(M_(N_, Lk, 'GREATER_THAN', idx.outputs[0], M_(N_, Lk, 'MULTIPLY', ds[1], float(count))), de.inputs["Selection"])
    sc = N_.new("ShaderNodeVectorMath"); sc.operation = 'SCALE'; Lk.new(pos.outputs[0], sc.inputs[0]); Lk.new(ds[0], sc.inputs["Scale"])
    setp = N_.new("GeometryNodeSetPosition"); Lk.new(de.outputs[0], setp.inputs["Geometry"]); Lk.new(sc.outputs[0], setp.inputs["Position"])
    mp = N_.new("GeometryNodeMeshToPoints"); Lk.new(setp.outputs[0], mp.inputs["Mesh"]); Lk.new(dr[0], mp.inputs["Radius"])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(mp.outputs[0], sm.inputs["Geometry"]); Lk.new(sm.outputs[0], go.inputs[0])
    return ng

def cloud_mat(name, rgb, strength):
    """every grain is a tiny metal sphere, lit + shadowed; Value 'gain' = extra glow"""
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); p = N_.new("ShaderNodeBsdfPrincipled")
    col = N_.new("ShaderNodeRGB"); col.outputs[0].default_value = (*rgb, 1)
    rnd = N_.new("ShaderNodeTexWhiteNoise")
    try: rnd.noise_dimensions = '3D'
    except Exception: pass
    shade = N_.new("ShaderNodeMix"); shade.data_type = 'RGBA'; shade.blend_type = 'MULTIPLY'; shade.inputs[0].default_value = 0.35
    Lk.new(col.outputs[0], shade.inputs[6]); Lk.new(rnd.outputs["Color"], shade.inputs[7])
    Lk.new(shade.outputs[2], p.inputs["Base Color"])
    p.inputs["Metallic"].default_value = 0.75; p.inputs["Roughness"].default_value = 0.32
    gain = N_.new("ShaderNodeValue"); gain.outputs[0].default_value = 0.0
    try:
        Lk.new(col.outputs[0], p.inputs["Emission Color"]); Lk.new(M_(N_, Lk, 'MULTIPLY', gain.outputs[0], strength), p.inputs["Emission Strength"])
    except Exception: pass
    Lk.new(p.outputs[0], out.inputs[0])
    return m, gain

def build_lights():
    import mathutils
    def light(name, loc, energy, rgb):
        ld = bpy.data.lights.new(name, 'SUN'); ld.energy = energy * BRIGHT; ld.color = rgb
        try: ld.use_shadow = True
        except Exception: pass
        o = link(bpy.data.objects.new(name, ld)); o.location = loc
        o.rotation_euler = (mathutils.Vector((0, 0, 0)) - mathutils.Vector(loc)).to_track_quat('-Z', 'Y').to_euler()
        return ld
    k = light("Key", (-60, -90, 110), 5.0, (1.0, 0.97, 0.92))
    try: k.angle = math.radians(1.0)
    except Exception: pass
    light("Rim", (70, 120, 30), 3.0, (0.75, 0.85, 1.0))
    light("Fill", (100, -40, -50), 0.8, (0.85, 0.9, 1.0))

def build_world_metal():
    """black to the camera, a soft cool sky for the metal to reflect"""
    w = bpy.context.scene.world or bpy.data.worlds.new("World")
    bpy.context.scene.world = w; w.use_nodes = True
    N_, Lk = w.node_tree.nodes, w.node_tree.links
    for n in list(N_): N_.remove(n)
    out = N_.new("ShaderNodeOutputWorld"); lp = N_.new("ShaderNodeLightPath")
    sky = N_.new("ShaderNodeBackground"); sky.inputs["Strength"].default_value = 0.4
    tc = N_.new("ShaderNodeTexCoord"); sep = N_.new("ShaderNodeSeparateXYZ"); Lk.new(tc.outputs["Generated"], sep.inputs[0])
    rp = N_.new("ShaderNodeValToRGB"); rp.color_ramp.elements[0].color = (0.01, 0.012, 0.02, 1); rp.color_ramp.elements[1].color = (0.45, 0.52, 0.65, 1)
    Lk.new(sep.outputs[2], rp.inputs[0]); Lk.new(rp.outputs[0], sky.inputs["Color"])
    blk = N_.new("ShaderNodeBackground"); blk.inputs["Color"].default_value = (0, 0, 0, 1); blk.inputs["Strength"].default_value = 0
    mx = N_.new("ShaderNodeMixShader"); Lk.new(lp.outputs["Is Camera Ray"], mx.inputs[0])
    Lk.new(sky.outputs[0], mx.inputs[1]); Lk.new(blk.outputs[0], mx.inputs[2]); Lk.new(mx.outputs[0], out.inputs[0])

# ---------------- camera ----------------
def cam_at(f):
    t = T[f]; z = ZIN[f]
    dist = math.exp(math.log(150.0) * (1 - z) + math.log(52.0) * z) * (1 - 0.05 * ef(t / 2.0)) * (1 + 0.12 * PAN[f])
    phi = 0.16 * t + 0.5
    tilt = math.radians(16 + 5 * math.sin(t * 0.3))
    return dist, phi, tilt, -0.15 * PAN[f]

# ---------------- build ----------------
def build():
    import mathutils
    scene = bpy.context.scene
    clear_scene()
    print("[1/4] Sampling the mercury atoms...")
    shells = [("6s", shell(6, 0, N6S, R6, 6), HG6, 0.4, True), ("5d", shell(5, 2, N5D, R5, 5), HG5, 0.5, False),
              ("core", shell(1, 0, NCORE, RC, 1), HGC, 0.9, False)]

    print("[2/4] Camera...")
    C = np.zeros((NF, 3)); EUL = np.zeros((NF, 3)); RM = np.zeros((NF, 3, 3)); DIST = np.zeros(NF); SH = np.zeros(NF); PHI = np.zeros(NF)
    for f in range(NF):
        dist, phi, tilt, shy = cam_at(f)
        cam = np.array([math.sin(phi) * math.cos(tilt), -math.cos(phi) * math.cos(tilt), math.sin(tilt)]) * dist
        fwd = -cam / np.linalg.norm(cam); right = np.cross(fwd, [0, 0, 1]); right /= np.linalg.norm(right); up = np.cross(right, fwd)
        R = np.stack([right, up, -fwd], 1); C[f] = cam; RM[f] = R; DIST[f] = dist; SH[f] = shy; PHI[f] = phi
        EUL[f] = mathutils.Matrix(R.tolist()).to_euler('XYZ')
    EUL = np.unwrap(EUL, axis=0)
    cd = bpy.data.cameras.new("Camera"); cd.lens = LENS; cd.sensor_fit = 'VERTICAL'; cd.sensor_height = 36
    cd.clip_start = 0.3; cd.clip_end = 2000
    camo = link(bpy.data.objects.new("Camera", cd)); scene.camera = camo
    for j in range(3): bake(camo, "location", j, C[:, j]); bake(camo, "rotation_euler", j, EUL[:, j])
    bake(cd, "shift_y", None, SH)

    print("[3/4] Atoms...")
    Dr = link(bpy.data.objects.new("Drive_radius", None)); Dr.hide_render = True
    bake(Dr, "location", 0, POINT_PX * PXK * DIST / 2 * (1 - 0.35 * ZIN))
    s6 = 1 - (1 - SHRINK) * ramp(*T_SHRINK)
    keep_others = np.clip(1 - 1.15 * ZIN, 0, 1)
    flash = np.exp(-((T - T_MELT[0] - 0.4) / 0.4) ** 2)
    groups = {}
    for nm, pts, rgb, strength, is6 in shells:
        me = bpy.data.meshes.new("Hg_" + nm); me.vertices.add(len(pts)); me.vertices.foreach_set("co", pts.ravel()); me.update()
        m, gain = cloud_mat("Hg_" + nm, rgb, strength)
        bake(gain.outputs[0], "default_value", None, 0.15 + 0.6 * flash + (0.4 * ZIN if nm == "core" else 0), owner=m.node_tree)
        for centre in (True, False):
            Ds = link(bpy.data.objects.new(f"Drive_{nm}_{'centre' if centre else 'others'}", None)); Ds.hide_render = True
            bake(Ds, "location", 0, s6 if is6 else np.ones(NF)); bake(Ds, "location", 1, np.ones(NF) if centre else keep_others)
            groups[(nm, centre)] = (me, cloud_group(f"Cloud_{nm}_{centre}", Ds, Dr, m, len(pts)))
    rng = np.random.default_rng(80); g = GRID; half = (g - 1) / 2
    sites = np.array([[(i - half) * SPACING, (j - half) * SPACING, (k - half) * SPACING] for i in range(g) for j in range(g) for k in range(g)])
    centre_i = int(np.argmin(np.linalg.norm(sites, axis=1)))
    for a, p0 in enumerate(sites):
        # liquid: every atom wanders on its own smooth path; crystal: only a small thermal jiggle
        ph = rng.uniform(0, 2 * np.pi, (3, 3)); fr = rng.uniform(0.25, 0.7, (3, 3))
        wander = np.stack([sum(np.sin(fr[d, h] * T * 2 + ph[d, h]) for h in range(3)) / 2.2 for d in range(3)], 1)
        amp = 0.35 + 7.5 * MELT
        drop = np.stack([np.zeros(NF), np.zeros(NF), -0.12 * p0[2] * MELT - 3.0 * MELT * (p0[2] > 0)], 1)
        loc = p0[None, :] * (1 - 0.15 * MELT)[:, None] + wander * amp[:, None] + drop
        if a == centre_i: loc = loc * (1 - ZIN)[:, None]                      # the atom we dive into sits still in the middle
        rot = rng.uniform(0, 2 * np.pi, 3)
        for nm, *_ in shells:
            me, ng = groups[(nm, a == centre_i)]
            ob = link(bpy.data.objects.new(f"Hg{a:02d}_{nm}", me)); ob.modifiers.new("cloud", 'NODES').node_group = ng
            ob.rotation_euler = rot
            for j in range(3): bake(ob, "location", j, loc[:, j])
    # bonds between neighbours of the crystal
    D = link(bpy.data.objects.new("Drive_line", None)); D.hide_render = True
    bake(D, "location", 1, 2.4 / 2 * PXK * DIST)
    bonds = [[tuple(sites[i]), tuple(sites[j])] for i in range(len(sites)) for j in range(i + 1, len(sites))
             if abs(np.linalg.norm(sites[i] - sites[j]) - SPACING) < 1e-3]
    bm, bv = glow_mat("Bonds", (0.55, 0.85, 1.0), 6.0); lines_obj("Bonds", bonds, D, bm, 1.0)
    bake(bv.outputs[0], "default_value", None, fade([(0, 0), (3.4, 0), (4.2, 0.7), (4.7, 0), (15.0, 0), (15.8, 1.0), (T_BONDS[0], 1.0), (T_BONDS[1], 0.05), (19.5, 0), (SECONDS, 0)]), owner=bm.node_tree)
    # contraction rings around the centre atom
    r_edge = R6 * 0.86
    dash = [[(r_edge * math.cos(a), 0, r_edge * math.sin(a)) for a in np.linspace(a0, a0 + 0.10, 4)] for a0 in np.arange(0, 2 * math.pi, 0.2)]
    full = [[(r_edge * math.cos(a), 0, r_edge * math.sin(a)) for a in np.linspace(0, 2 * math.pi, 181)]]
    rings = []
    for nm, segs, rgb, st in (("RingBefore", dash, (1, 1, 1), 2.5), ("RingNow", full, (0.55, 0.85, 1.0), 5.0)):
        mt, mv = glow_mat(nm, rgb, st); o = lines_obj(nm, segs, D, mt, 0.8)
        bake(o, "rotation_euler", 2, PHI); bake(mv.outputs[0], "default_value", None, fade(show(9.3, 13.4)), owner=mt.node_tree)
        rings.append(o)
    for j in range(3): bake(rings[1], "scale", j, s6)

    print("[4/4] Text...")
    imgs, font = load_assets()
    def hud_loc(xs, ys, depth=0.25):
        d = DIST * depth
        return np.array([C[f] + RM[f] @ np.array([(xs[f] - 540) * PXK * d[f], (960 - ys[f]) * PXK * d[f], -d[f]]) + RM[f][:, 1] * SH[f] * 2 * KH * d[f] for f in range(NF)])
    def hud(ob_, cx, cy, depth=0.25):
        loc = hud_loc(np.full(NF, float(cx)), np.full(NF, float(cy)), depth); d = DIST * depth
        for j in range(3): bake(ob_, "location", j, loc[:, j]); bake(ob_, "rotation_euler", j, EUL[:, j]); bake(ob_, "scale", j, PXK * d)
    def pic(name, cx, cy, pairs):
        im = imgs[name]; w_, h_ = im.size
        me_ = bpy.data.meshes.new(name)
        me_.from_pydata([(-w_ / 2, -h_ / 2, 0), (w_ / 2, -h_ / 2, 0), (w_ / 2, h_ / 2, 0), (-w_ / 2, h_ / 2, 0)], [], [(0, 1, 2, 3)])
        uv_ = me_.uv_layers.new(); uv_.data.foreach_set("uv", [0, 0, 1, 0, 1, 1, 0, 1])
        o_ = link(bpy.data.objects.new(name, me_)); m_, v_ = image_mat(name, im); me_.materials.append(m_)
        hud(o_, cx, cy); bake(v_.outputs[0], "default_value", None, fade(pairs), owner=m_.node_tree)
        return o_
    pic("t_hook", 540, 210, [(0, 1), (2.0, 1), (2.3, 0), (SECONDS, 0)])
    pic("t_noein", 540, 200, show(2.2, 4.4, 0.4))
    pic("t_speed", 540, 200, show(4.7, 9.2))
    pic("speed_f", 540, 1725, show(5.6, 9.2)); pic("speed_l", 540, 1585, show(5.8, 9.2))
    pic("t_shrink", 540, 200, show(9.4, 14.6))
    pic("shell", 540, 1690, show(10.0, 14.6))
    pic("t_hands", 540, 200, show(15.0, 19.0))
    pic("bonds_l", 540, 1690, show(16.0, 19.0))
    pic("t_melt", 540, 190, show(19.4, 25.0))
    pic("thermo", 880, 1450, show(19.4, 25.6))
    pic("deg", 520, 1330, show(19.8, 25.6))
    pic("lab_no", 380, 1395, show(19.8, 21.4, 0.4, 0.3)); pic("lab_real", 380, 1395, show(21.6, 25.6, 0.3))
    pic("solid", 380, 1560, show(20.0, 25.6)); pic("liquid", 380, 1660, show(23.0, 25.6))
    pic("t_end", 540, 230, [(0, 0), (25.4, 0), (26.1, 1), (SECONDS, 1)])
    pic("t_next", 540, 1700, [(0, 0), (27.0, 0), (27.6, 1), (SECONDS, 1)])
    pic("note", 540, 1835, [(0, 0), (25.4, 0), (26.1, 1), (SECONDS, 1)])
    pic("handle", 540, 1880, [(0, 1), (SECONDS, 1)])
    pic("cat", 760, 760, [(0, 0), (T_CAT[0], 0), (T_CAT[0] + 0.08, 0.9), (T_CAT[1] - 0.08, 0.9), (T_CAT[1], 0), (SECONDS, 0)])
    # thermometer marker: +82 C -> -39 C
    temp = 82 - 121 * ramp(*T_TEMP)
    mk = pic("bulb", 820, 1000, show(19.6, 25.6))
    my = (1450 - 380) + 600 - (temp + 60) / 170 * 520
    loc = hud_loc(np.full(NF, 820.0), my)
    for j in range(3): bake(mk, "location", j, loc[:, j])
    # live counters: speed (0 -> 58) and temperature (82 -> -39)
    Dv = link(bpy.data.objects.new("Drive_counters", None)); Dv.hide_render = True
    bake(Dv, "location", 0, 58 * ramp(*T_SPEED) - 0.49); bake(Dv, "location", 1, temp - 0.49)
    for axis, cx, cy, rgb, pairs in ((0, 540, 1505, (0.6, 0.85, 1.0), show(5.8, 9.2)), (1, 400, 1335, (1.0, 1.0, 1.0), show(19.8, 25.6))):
        cm, cv = glow_mat(f"CounterMat{axis}", rgb, 1.0)
        co = link(bpy.data.objects.new(f"Counter{axis}", bpy.data.meshes.new(f"CounterMesh{axis}")))
        co.modifiers.new("cnt", 'NODES').node_group = counter_group(Dv, axis, font, cm)
        hud(co, cx, cy); bake(cv.outputs[0], "default_value", None, fade(pairs), owner=cm.node_tree)

    build_world_metal(); build_lights(); setup_render(scene); add_bloom(scene)
    try: scene.eevee.use_shadows = True
    except Exception: pass
    for scr in bpy.data.screens:
        for area in scr.areas:
            if area.type == 'VIEW_3D':
                for sp_ in area.spaces:
                    if sp_.type == 'VIEW_3D':
                        try: sp_.shading.use_compositor = 'DISABLED'
                        except Exception: pass
    scene.frame_set(1)
    print(f"Ready: {NF} frames, {len(sites)} atoms, {len(sites) * (N6S + N5D + NCORE):,} grains. Ctrl+F12 -> {scene.render.filepath}")

def _deferred():
    try: build()
    except Exception:
        import traceback; traceback.print_exc()
    return None

if bpy.app.background:
    build()
else:
    print("Building... (Window > Toggle System Console to watch)")
    bpy.app.timers.register(_deferred, first_interval=0.2)
